function permutations(s: string): string[] {
  if (s.length <= 1) return [s];
  const result: string[] = [];
  for (let i = 0; i < s.length; i++) {
    const char = s[i];
    const rest = s.slice(0, i) + s.slice(i + 1);
    for (const perm of permutations(rest)) {
      result.push(char + perm);
    }
  }
  return result;
}

